fn solve(s: Vec<char>) -> Vec<char> {
    // We'll use a bitmask to record which of 'a', 'b', 'c' we have seen.
    // 'a' -> bit 0 (value 1)
    // 'b' -> bit 1 (value 2)
    // 'c' -> bit 2 (value 4)
    // If at the end the mask is 1|2|4 == 7, then we've seen all three exactly once.
    let mut mask = 0;
    for &ch in s.iter().take(3) {
        mask |= match ch {
            'a' => 1,
            'b' => 2,
            'c' => 4,
            _ => 0, // By problem statement, this branch should never happen.
        };
    }

    if mask == 7 {
        // We have seen 'a', 'b', and 'c' exactly once each.
        "Yes\n".chars().collect()
    } else {
        "No\n".chars().collect()
    }
}

